package io.knowledgebrain.activity;
import java.time.*;import java.util.*;import java.net.URI;
import io.knowledgebrain.contracts.learning.roadmap.v1.RoadmapEventEnvelopeV1;
import io.knowledgebrain.contracts.content.bookmark.v1.*;
import io.knowledgebrain.contracts.content.question.v1.*;
import io.knowledgebrain.contracts.content.decision.v1.*;
import io.knowledgebrain.contracts.content.recordconcepts.v1.*;
/** Immutable Content facts. Never resolve or infer a historical Concept title. */
final class ContentActivity {
 private static IllegalArgumentException bad(){return ActivityEvent.invalid();}
 private static String text(String v,int max,boolean title){if(v.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>max||title&&(v.isBlank()||v.codePointCount(0,v.length())>200)||v.codePoints().anyMatch(c->c>=0xd800&&c<=0xdfff||Character.isISOControl(c)&&!(!title&&(c=='\n'||c=='\r'||c=='\t'))))throw bad();return v;}
 private static String url(String v){try{if(v.length()>2048||!v.matches("[\\x21-\\x7e]+")||v.indexOf('\\')>=0)throw bad();var u=new URI(v);if(!Set.of("http","https").contains(Optional.ofNullable(u.getScheme()).orElse("").toLowerCase(Locale.ROOT))||u.isOpaque()||u.getHost()==null||u.getRawUserInfo()!=null||u.getPort()==0||u.getPort()>65535||!u.getRawAuthority().equals(u.getHost()+(u.getPort()<0?"":":"+u.getPort())))throw bad();return v;}catch(java.net.URISyntaxException ex){throw bad();}}
 static boolean target(ActivityEvent e){var c=e.content();if(c==null||e.planning()!=null||e.roadmapId()!=null||e.nodeId()!=null||c.recordId()==null||c.recordVersion()<1||!Set.of("BOOKMARK","QUESTION","DECISION").contains(c.recordType()))return false;String path="/api/spaces/"+e.spaceId()+"/";if(e.kind().equals("RECORD_CONCEPTS"))path+="record-concepts/"+c.recordType()+"/"+c.recordId();else{if(!e.kind().equals(c.recordType())||!e.aggregateId().equals(c.recordId())||c.recordVersion()!=e.sourceVersion())return false;path+=c.recordType().toLowerCase(Locale.ROOT)+"s/"+c.recordId();}return e.targetPath().equals(path);}
 static ActivityEvent decode(RoadmapEventEnvelopeV1 e,String kind)throws com.google.protobuf.InvalidProtocolBufferException {
  UUID aggregate=ActivityEvent.id(e.getAggregateId()),record;long version,recordVersion;String title="",detail="",state,type,recordType=kind,status=null,url=null,answer=null,outcome=null,rationale=null,alternatives=null,created=null,updated=null;List<ActivityEvent.Link> links=List.of();
  switch(kind){
   case "BOOKMARK"->{var p=BookmarkChangedPayloadV1.parseFrom(e.getPayload());record=ActivityEvent.id(p.getBookmarkId());ActivityEvent.id(p.getRevisionId());version=p.getVersion();recordVersion=version;if(!p.getVisibility().equals("PRIVATE"))throw bad();title=text(p.getTitle(),800,true);detail=text(p.getMemo(),32768,false);url=url(p.getUrl());state=p.getState();created=p.getCreatedAt();updated=p.getUpdatedAt();type="Bookmark";}
   case "QUESTION"->{var p=QuestionChangedPayloadV1.parseFrom(e.getPayload());record=ActivityEvent.id(p.getQuestionId());ActivityEvent.id(p.getRevisionId());version=p.getVersion();recordVersion=version;if(!p.getVisibility().equals("PRIVATE"))throw bad();title=text(p.getTitle(),800,true);detail=text(p.getContext(),16384,false);answer=text(p.getAnswer(),16384,false);status=p.getStatus();if(!Set.of("OPEN","ANSWERED").contains(status)||status.equals("ANSWERED")&&answer.isBlank())throw bad();state=p.getState();created=p.getCreatedAt();updated=p.getUpdatedAt();type="Question";}
   case "DECISION"->{var p=DecisionChangedPayloadV1.parseFrom(e.getPayload());record=ActivityEvent.id(p.getDecisionId());ActivityEvent.id(p.getRevisionId());version=p.getVersion();recordVersion=version;if(!p.getVisibility().equals("PRIVATE"))throw bad();title=text(p.getTitle(),800,true);detail=text(p.getContext(),8192,false);outcome=text(p.getOutcome(),8192,false);rationale=text(p.getRationale(),8192,false);alternatives=text(p.getAlternatives(),8192,false);status=p.getStatus();if(!Set.of("DRAFT","DECIDED").contains(status)||status.equals("DECIDED")&&(outcome.isBlank()||rationale.isBlank()))throw bad();state=p.getState();created=p.getCreatedAt();updated=p.getUpdatedAt();type="Decision";}
   case "RECORD_CONCEPTS"->{var p=RecordConceptsChangedPayloadV1.parseFrom(e.getPayload());if(!aggregate.equals(ActivityEvent.id(p.getAssociationId())))throw bad();ActivityEvent.id(p.getRevisionId());record=ActivityEvent.id(p.getRecordId());recordType=p.getRecordType();if(!Set.of("BOOKMARK","QUESTION","DECISION").contains(recordType)||!p.getRecordState().equals("ACTIVE")||p.getLinksCount()>20)throw bad();version=p.getVersion();recordVersion=p.getRecordVersion();state=p.getRecordState();var ids=new HashSet<UUID>();var concepts=new HashSet<UUID>();var rows=new ArrayList<ActivityEvent.Link>();for(var link:p.getLinksList()){var id=ActivityEvent.id(link.getLinkId());var concept=ActivityEvent.id(link.getConceptId());if(!ids.add(id)||!concepts.add(concept))throw bad();rows.add(new ActivityEvent.Link(id,concept));}links=List.copyOf(rows);title=switch(recordType){case "BOOKMARK"->"북마크 개념 연결";case "QUESTION"->"질문 개념 연결";default->"결정 개념 연결";};type="RecordConceptLinks";if(!e.getEventType().equals("RecordConceptsChanged"))throw bad();}
   default->throw bad();
  }
  if(version<1||recordVersion<1||!Set.of("ACTIVE","RETIRED").contains(state)||!e.getAggregateType().equals(type))throw bad();
  if(!kind.equals("RECORD_CONCEPTS")&&(!aggregate.equals(record)||!Set.of(type+"Created",type+"Updated",type+"Retired").contains(e.getEventType())||e.getEventType().equals(type+"Created")&&version!=1||state.equals("RETIRED")!=e.getEventType().equals(type+"Retired")||Instant.parse(updated).toEpochMilli()!=e.getOccurredAtEpochMillis()||Instant.parse(created).isAfter(Instant.parse(updated))))throw bad();
  var content=new ActivityEvent.Content(recordType,record,recordVersion,status,url,answer,outcome,rationale,alternatives,links);
  String path="/api/spaces/"+e.getSpaceId()+"/"+(kind.equals("RECORD_CONCEPTS")?"record-concepts/"+recordType+"/"+record:recordType.toLowerCase(Locale.ROOT)+"s/"+record);
  return new ActivityEvent(ActivityEvent.id(e.getEventId()),ActivityEvent.id(e.getSpaceId()),ActivityEvent.id(e.getActorId()),e.getTraceId(),Instant.ofEpochMilli(e.getOccurredAtEpochMillis()).toString(),kind,e.getEventType(),type,aggregate,version,null,null,title,"",state,detail,null,null,0,path,null,content,null,null,null,null,null);
 }
}
